INSERT INTO vehicle (
    vehicle_id, company_id, org_id, lock_id, controller_id, plate_number, filing_code,
    model, batch_no, operation_city_code, operation_area_code, launch_date,
    lifecycle_status
) VALUES (
    #{vehicleId}, #{companyId}, #{orgId}, #{lockId}, #{controllerId}, #{plateNumber}, #{filingCode},
    #{model}, #{batchNo}, #{operationCityCode}, #{operationAreaCode}, #{launchDate}, #{lifecycleStatus}
)
ON CONFLICT DO NOTHING

mapper.select:
SELECT FROM vehicle v LEFT JOIN vehicle_latest l ON l.vehicle_id = v.vehicle_id
1 = 1
ORDER BY v.vehicle_id LIMIT #{limit} OFFSET #{offset}

SELECT reported_at, longitude, latitude, accuracy_meters, speed_kmh,
       direction_degrees, battery_percent, lock_status, ride_status
FROM vehicle_position
WHERE vehicle_id = #{vehicleId}
  AND reported_at >= #{startTime}
  AND reported_at <= #{endTime}
ORDER BY reported_at
LIMIT #{limit}
